assert_columns "seats" "position_in_row:NO;room_code:NO;row_label:NO;seat_number:NO"
assert_type "seats" "position_in_row" "integer"
assert_type "seats" "room_code" "text"
assert_type "seats" "row_label" "text"
assert_type "seats" "seat_number" "integer"
# Test descriptions are in English. SQL assertions use the isolated test database.
assert_equals "seats has the required primary key" "SELECT GROUP_CONCAT(COLUMN_NAME ORDER BY COLUMN_NAME) FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='seats' AND CONSTRAINT_NAME='PRIMARY'" "room_code,seat_number"
assert_equals "Physical positions have a unique index" "SELECT COUNT(*) FROM (SELECT INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='seats' AND NON_UNIQUE=0 GROUP BY INDEX_NAME HAVING GROUP_CONCAT(COLUMN_NAME ORDER BY COLUMN_NAME)='position_in_row,room_code,row_label') AS matching_indexes" "1"
assert_accepts "Seat numbers can repeat in different rooms" "INSERT INTO seats VALUES('A01',1,'A',1),('B01',1,'A',1),('A01',2,'A',2)"
assert_rejects "A room cannot repeat a seat number" "1062" "INSERT INTO seats VALUES('A01',1,'B',1)"
assert_rejects "A physical position cannot be reused" "1062" "INSERT INTO seats VALUES('A01',3,'A',1)"
assert_rejects "A seat number must be positive" "3819" "INSERT INTO seats VALUES('A01',0,'B',1)"
assert_rejects "A row position must be positive" "3819" "INSERT INTO seats VALUES('A01',3,'B',0)"
